<script lang="ts">
  import { enhance } from '$app/forms';
  import { untrack } from 'svelte';
  import type { PageProps } from './$types';
  let { data, form }: PageProps = $props();
  let tab = $state('students');
  const d = $derived(data.academic);
  let cpmks = $state<any[]>(untrack(() => structuredClone(data.academic?.policy.cpmks ?? [])));
  let assessments = $state<any[]>(untrack(() => structuredClone(data.academic?.policy.assessments ?? [])));
  let cpls = $state<any[]>(untrack(() => Object.entries(data.academic?.policy.cpl_targets ?? {}).map(([id,target]) => ({id,target}))));
  $effect(() => { if (data.academic) { cpmks = structuredClone(data.academic.policy.cpmks); assessments = structuredClone(data.academic.policy.assessments); cpls = Object.entries(data.academic.policy.cpl_targets).map(([id, target]) => ({ id, target })); } });
  const policy = $derived({ cpmks: cpmks.map(c => ({ ...c, cpl_mapping: Object.fromEntries(cpls.map(p => [p.id, c.cpl_mapping[p.id] ?? 0]).filter(([, v]) => Number(v) > 0)) })), assessments, cpl_targets: Object.fromEntries(cpls.map(c => [c.id, c.target])) });
</script>
<svelte:head><title>Data Akademik — Campus Assistant</title></svelte:head>
<div class="shell"><aside><a class="brand" href="/">CA <span>Campus Assistant</span></a><p class="caption">WORKSPACE DOSEN</p><a href={d ? `/?class=${encodeURIComponent(d.id)}` : '/'}>Ringkasan kelas</a><a class="active" href="/academic">Data Akademik</a><a href={d ? `/?class=${encodeURIComponent(d.id)}#interventions` : '/'}>Intervensi</a><a href={d ? `/?class=${encodeURIComponent(d.id)}#roi` : '/'}>Evaluasi pilot</a><a href={d ? `/reports?class=${encodeURIComponent(d.id)}` : '/reports'}>Laporan & ekspor</a><div class="note">Data tersimpan di database.<br/>Nilai kosong berarti belum dinilai.</div></aside><main><header><span>Workspace / Data Akademik</span><a href="/">Kembali ke dashboard →</a></header><section><div class="title"><div><p class="caption">ACADEMIC DATA</p><h1>Kelola bukti pembelajaran.</h1><p>Kelas, mahasiswa, pemetaan, dan nilai dalam satu tempat.</p></div><form method="GET"><label>Kelas<select name="class" onchange={(e) => e.currentTarget.form?.requestSubmit()}>{#each data.classes as c}<option value={c.id} selected={c.id === d?.id}>{c.name}</option>{/each}</select></label></form></div>
{#if form?.error || data.error}<div class="alert" role="alert">{form?.error || data.error}</div>{/if}{#if form?.success}<div class="notice" role="status">{form.success}</div>{/if}
<nav>{#each [['students','Mahasiswa & kelas'],['scores','Input nilai'],['policy','CPMK / CPL'],['import','Impor CSV'],['audit','Riwayat perubahan']] as item}<button class:active={tab===item[0]} onclick={() => tab=item[0]}>{item[1]}</button>{/each}</nav>
{#if tab==='students'}<div class="grid"><article><h2>Tambah kelas</h2><p>Kelas baru memakai pemetaan contoh yang dapat Anda sesuaikan.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="op" value="class"/><label>ID kelas<input name="id" placeholder="FDA-01" pattern="[A-Za-z0-9_-]+" maxlength="40" required/></label><label>Nama kelas<input name="name" placeholder="Fundamental Data Analyst — SI-01" minlength="3" maxlength="120" required/></label><button class="primary">Simpan kelas</button></form></article>{#if d}<article><h2>Tambah mahasiswa</h2><p>ID mahasiswa harus unik di seluruh pilot.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="op" value="student"/><input type="hidden" name="class_id" value={d.id}/><label>ID / NIM<input name="id" pattern="[A-Za-z0-9_-]+" maxlength="40" required/></label><label>Nama<input name="name" minlength="2" maxlength="120" required/></label><button class="primary">Simpan mahasiswa</button></form></article>{/if}</div>{#if d}<article><h2>Daftar mahasiswa · {d.students.length}</h2>{#each d.students as s}<form class="row" method="POST" action="?/save" use:enhance><input type="hidden" name="op" value="rename"/><input type="hidden" name="class_id" value={d.id}/><input type="hidden" name="id" value={s.id}/><strong>{s.id}</strong><input aria-label={`Nama ${s.id}`} name="name" value={s.name} minlength="2" maxlength="120" required/><button>Simpan nama</button></form>{/each}{#if !d.students.length}<p>Tambahkan mahasiswa pertama untuk mulai input nilai.</p>{/if}</article>{/if}
{:else if d && tab==='scores'}<article><h2>Input nilai assessment</h2><p>Nilai 0–100. Kosongkan sel untuk status belum dinilai. Menyimpan perubahan membuat draft lama perlu diperiksa ulang.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="op" value="scores"/><input type="hidden" name="class_id" value={d.id}/><input type="hidden" name="revision" value={d.revision}/><div class="scroll"><table><thead><tr><th>Mahasiswa</th>{#each d.policy.assessments as a}<th>{a.id}<small>{a.cpmk_id} · bobot {a.weight}</small></th>{/each}</tr></thead><tbody>{#each d.students as s}<tr><td>{s.name}<small>{s.id}</small></td>{#each d.policy.assessments as a}<td><input aria-label={`${s.id} ${a.id}`} name={`score_${s.id}_${a.id}`} type="number" min="0" max="100" step="0.01" value={d.scores[s.id]?.[a.id] ?? ''} placeholder="—"/></td>{/each}</tr>{/each}</tbody></table></div><button class="primary" disabled={!d.students.length}>Simpan seluruh nilai</button></form></article>
{:else if d && tab==='policy'}<article><h2>Target dan pemetaan capaian</h2><p>Bobot assessment per CPMK = 1. Bobot pemetaan CPL keluar per CPMK = 1. Assessment yang sudah memiliki nilai tidak dapat dihapus.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="op" value="policy"/><input type="hidden" name="class_id" value={d.id}/><input type="hidden" name="revision" value={d.revision}/><input type="hidden" name="policy" value={JSON.stringify(policy)}/><h3>CPL mata kuliah</h3>{#each cpls as c}<div class="row"><label>ID CPL<input bind:value={c.id} required/></label><label>Target<input type="number" min="0" max="100" bind:value={c.target} required/></label></div>{/each}<button type="button" onclick={() => cpls.push({id:`CPL-${cpls.length+1}`,target:75})}>+ Tambah CPL</button><h3>CPMK dan kontribusi ke CPL</h3>{#each cpmks as c}<div class="mapping"><label>ID CPMK<input bind:value={c.id} required/></label><label>Target<input type="number" min="0" max="100" bind:value={c.target} required/></label>{#each cpls as p}<label>Bobot → {p.id}<input type="number" min="0" max="1" step="0.01" bind:value={c.cpl_mapping[p.id]} placeholder="0"/></label>{/each}</div>{/each}<button type="button" onclick={() => cpmks.push({id:`CPMK-${cpmks.length+1}`,target:75,cpl_mapping:{}})}>+ Tambah CPMK</button><h3>Assessment</h3>{#each assessments as a}<div class="mapping"><label>ID assessment<input bind:value={a.id} required/></label><label>CPMK<select bind:value={a.cpmk_id}>{#each cpmks as c}<option>{c.id}</option>{/each}</select></label><label>Bobot<input type="number" min="0.01" max="1" step="0.01" bind:value={a.weight} required/></label></div>{/each}<button type="button" onclick={() => assessments.push({id:`ASM-${assessments.length+1}`,cpmk_id:cpmks[0]?.id,weight:1})}>+ Tambah assessment</button><div><button class="primary">Validasi & simpan pemetaan</button></div></form></article>
{:else if d && tab==='import'}<article><h2>Impor nilai CSV</h2><p>Mahasiswa dan assessment harus sudah terdaftar. Header: <code>student_id,assessment_id,value</code>. Maksimal 2000 baris / 200 KB. Nilai kosong = belum dinilai.</p><pre>student_id,assessment_id,value\nSTD-003,ASM-02,80\nSTD-010,ASM-02,</pre><form method="POST" action="?/save" enctype="multipart/form-data" use:enhance><input type="hidden" name="op" value="preview"/><input type="hidden" name="class_id" value={d.id}/><label>File CSV<input type="file" name="file" accept=".csv,text/csv" required/></label><button class="primary">Preview & validasi</button></form></article>{#if form?.preview}<article><h2>Hasil preview · {form.preview.rows.length} baris valid</h2>{#each form.preview.errors as e}<div class="alert">Baris {e.row}: {e.message}</div>{/each}<div class="scroll"><table><thead><tr><th>Mahasiswa</th><th>Assessment</th><th>Nilai</th></tr></thead><tbody>{#each form.preview.rows as r}<tr><td>{r.student_id}</td><td>{r.assessment_id}</td><td>{r.value ?? 'Belum dinilai'}</td></tr>{/each}</tbody></table></div>{#if form.preview.valid}<form method="POST" action="?/save" use:enhance><input type="hidden" name="op" value="import"/><input type="hidden" name="class_id" value={d.id}/><input type="hidden" name="batch" value={JSON.stringify({expected_revision:form.preview.expected_revision,rows:form.preview.rows})}/><button class="primary">Konfirmasi simpan {form.preview.rows.length} nilai</button></form>{/if}</article>{/if}
{:else if d && tab==='audit'}<article><h2>Riwayat perubahan</h2><p>100 tindakan terakhir Anda pada kelas ini.</p><div class="scroll"><table><thead><tr><th>Waktu</th><th>Tindakan</th><th>Objek</th></tr></thead><tbody>{#each data.audit as a}<tr><td>{new Date(a.created*1000).toLocaleString('id-ID')}</td><td>{a.action}</td><td>{a.object_id}</td></tr>{/each}</tbody></table></div></article>{/if}
<footer>Campus Assistant · Data Akademik <span>Keputusan akademik berbasis bukti</span></footer></section></main></div>
<style>
:global(body){margin:0;background:#f5f7fb;color:#192b43;font:14px Inter,system-ui,sans-serif}:global(*){box-sizing:border-box}a{color:#0f4c9a;text-decoration:none}button,input,select{font:inherit}button{cursor:pointer;border:1px solid #dbe5f0;border-radius:8px;padding:10px 14px;background:white;color:#0f4c9a}button:disabled{opacity:.5;cursor:not-allowed}.shell{display:flex;min-height:100vh}aside{width:240px;padding:30px 22px;background:white;border-right:1px solid #e3eaf2;display:flex;flex-direction:column;gap:12px}.brand{font-weight:750;font-size:21px}.brand span{font-size:14px}.caption{font-size:10px;letter-spacing:1.6px;color:#8495a9;font-weight:700}aside>a:not(.brand){padding:12px;border-radius:8px;color:#6a7e95}.active{background:#edf4fd!important;color:#0f4c9a!important}.note{margin-top:auto;background:#eef8f3;padding:17px;border-radius:12px;line-height:1.8;color:#348260;font-size:12px}main{flex:1;min-width:0}header{padding:25px 36px;background:white;border-bottom:1px solid #e3eaf2;display:flex;justify-content:space-between;font-size:12px;color:#8090a4}section{padding:32px;max-width:1450px;margin:auto}.title{display:flex;justify-content:space-between;align-items:center;gap:20px}h1{font-size:30px;letter-spacing:-.8px;margin:10px 0}h2{font-size:18px;margin:0 0 12px}h3{font-size:14px;margin:24px 0 12px}p{color:#7a8c9f;line-height:1.7}nav{display:flex;gap:8px;flex-wrap:wrap;margin:25px 0}article{background:white;border:1px solid #e3eaf2;border-radius:14px;padding:24px;margin-bottom:20px;box-shadow:0 4px 15px #17385604}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}form{display:grid;gap:15px}label{display:grid;gap:7px;font-size:12px;color:#637b93}input,select{width:100%;padding:11px;border:1px solid #dbe5f0;border-radius:8px;background:white;color:#223951}.primary{background:#0f4c9a;border:0;color:white;justify-self:start}.row{display:flex;align-items:center;gap:15px;padding:12px 0;border-bottom:1px solid #edf1f6}.row strong{min-width:100px}.row input{flex:1}.row label{flex:1}.row button{white-space:nowrap}.mapping{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px;padding:16px;background:#f7faff;border-radius:10px}table{width:100%;border-collapse:collapse;text-align:left}td,th{padding:14px;border-bottom:1px solid #edf1f6;font-size:12px}th{background:#f8fafd;color:#7b8fa5}small{display:block;color:#8a9baf;margin-top:4px}td input{min-width:95px}pre{background:#f5f8fd;padding:15px;border-radius:8px;line-height:1.8;white-space:pre-wrap}.scroll{overflow:auto}.alert,.notice{padding:14px;border-radius:8px;margin:15px 0;line-height:1.6}.alert{background:#fff0ea;color:#a25b38}.notice{background:#eaf8f1;color:#258359}footer{display:flex;justify-content:space-between;padding:20px 0;color:#92a1b3;font-size:11px}@media(max-width:850px){aside{width:190px}section{padding:22px}.grid{grid-template-columns:1fr}.title{display:block}}@media(max-width:650px){.shell{display:block}aside{width:100%;flex-direction:row;flex-wrap:wrap;padding:16px;gap:4px}aside .brand{width:100%}.caption,.note{display:none}aside>a:not(.brand){font-size:11px;padding:8px}header{padding:16px}section{padding:18px}h1{font-size:24px}.row{flex-wrap:wrap}footer span{display:none}}
